1	@import url('https://fonts.googleapis.com/css2?family=DM+Sans:opsz,wght@9..40,400;9..40,500;9..40,600;9..40,700;9..40,800&family=Inter:wght@400;500;600;700&display=swap');
2	@import "tailwindcss";
3	@import "@heroui/styles";
4	
5	/* ═══════════════════════════════════════════════════
6	   GCCStartup v2.0 — Design Tokens & Foundation
7	   ═══════════════════════════════════════════════════ */
8	
9	@theme {
10	  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
11	  --font-heading: 'DM Sans', -apple-system, BlinkMacSystemFont, sans-serif;
12	
13	  --color-orange: #F26522;
14	  --color-orange-dark: #D4561A;
15	  --color-orange-light: #FEF1E9;
16	  --color-orange-hover: #E85A18;
17	
18	  --color-navy: #14204A;
19	  --color-navy-light: #1E2D5A;
20	  --color-navy-subtle: #F0F2F8;
21	
22	  --color-surface: #FFFFFF;
23	  --color-surface-alt: #F8FAFC;
24	  --color-canvas: #F1F3F7;
25	  --color-card: #FFFFFF;
26	
27	  --color-border: #E8ECF1;
28	  --color-border-hover: #D1D8E3;
29	
30	  --color-text: #1A1D26;
31	  --color-text-secondary: #5A6178;
32	  --color-text-tertiary: #8C93A7;
33	  --color-text-muted: #B4BAC9;
34	
35	  --color-success: #16A34A;
36	  --color-success-light: #DCFCE7;
37	  --color-error: #DC2626;
38	  --color-error-light: #FEE2E2;
39	  --color-warning: #D97706;
40	  --color-warning-light: #FEF3C7;
41	  --color-info: #2563EB;
42	  --color-info-light: #DBEAFE;
43	  --color-whatsapp: #25D366;
44	
45	  --radius-xs: 6px;
46	  --radius-sm: 8px;
47	  --radius-md: 12px;
48	  --radius-lg: 16px;
49	  --radius-xl: 20px;
50	  --radius-2xl: 24px;
51	  --radius-pill: 9999px;
52	
53	  --shadow-xs: 0 1px 2px rgba(0,0,0,0.04);
54	  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
55	  --shadow-md: 0 4px 12px rgba(0,0,0,0.06), 0 2px 4px rgba(0,0,0,0.04);
56	  --shadow-lg: 0 8px 24px rgba(0,0,0,0.08), 0 4px 8px rgba(0,0,0,0.04);
57	  --shadow-xl: 0 16px 48px rgba(0,0,0,0.1), 0 8px 16px rgba(0,0,0,0.06);
58	  --shadow-orange: 0 4px 16px rgba(242,101,34,0.25);
59	  --shadow-card: 0 2px 8px rgba(0,0,0,0.04), 0 0 1px rgba(0,0,0,0.06);
60	
61	  --spacing-page: 20px;
62	  --spacing-section: 28px;
63	}
64	
65	/* ─── Variable Aliases (for inline var() usage in components) ─── */
66	:root {
67	  --navy: var(--color-navy);
68	  --orange: var(--color-orange);
69	  --text-secondary: var(--color-text-secondary);
70	  --text-tertiary: var(--color-text-tertiary);
71	  --text-muted: var(--color-text-secondary);
72	  --border: var(--color-border);
73	  --surface: var(--color-surface);
74	  --surface-alt: var(--color-surface-alt);
75	  --success: var(--color-success);
76	  --error: var(--color-error);
77	  --warning: var(--color-warning);
78	  --blue: var(--color-info);
79	  --orange-lt: var(--color-orange-light);
80	  --sand: #F5F0E8;
81	  --card-hover: rgba(0,0,0,0.03);
82	}
83	
84	/* ─── Base Reset ─── */
85	*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
86	
87	html {
88	  -webkit-text-size-adjust: 100%;
89	  -webkit-font-smoothing: antialiased;
90	  -moz-osx-font-smoothing: grayscale;
91	  text-rendering: optimizeLegibility;
92	}
93	
94	html, body { height: 100%; overflow-x: hidden; }
95	
96	body {
97	  font-family: var(--font-sans);
98	  background: var(--color-canvas);
99	  color: var(--color-text);
100	  line-height: 1.5;
101	  min-height: 100dvh;
102	}
103	
104	/* ─── Accessibility ─── */
105	:focus-visible {
106	  outline: 2px solid var(--color-orange);
107	  outline-offset: 2px;
108	  border-radius: var(--radius-xs);
109	}
110	
111	.skip-link {
112	  position: absolute;
113	  top: -9999px;
114	  left: 16px;
115	  z-index: 9999;
116	  padding: 8px 16px;
117	  background: var(--color-orange);
118	  color: #FFFFFF;
119	  font-weight: 700;
120	  font-size: 13px;
121	  border-radius: var(--radius-sm);
122	  text-decoration: none;
123	  box-shadow: var(--shadow-md);
124	  transition: top 0.2s ease;
125	}
126	.skip-link:focus { top: 16px; }
127	
128	@media (prefers-reduced-motion: reduce) {
129	  *, *::before, *::after {
130	    animation-duration: 0.01ms !important;
131	    animation-iteration-count: 1 !important;
132	    transition-duration: 0.01ms !important;
133	  }
134	}
135	
136	/* ─── Custom Scrollbar ─── */
137	::-webkit-scrollbar { width: 4px; height: 4px; }
138	::-webkit-scrollbar-track { background: transparent; }
139	::-webkit-scrollbar-thumb { background: var(--color-border-hover); border-radius: 99px; }
140	::-webkit-scrollbar-thumb:hover { background: var(--color-text-muted); }
141	
142	/* ═══════════════════════════════════════════════════
143	   APP SHELL
144	   ═══════════════════════════════════════════════════ */
145	
146	.app-shell {
147	  display: flex;
148	  flex-direction: column;
149	  min-height: 100dvh;
150	  max-width: 100vw;
151	  overflow-x: hidden;
152	  background: var(--color-canvas);
153	}
154	
155	.app-page-content {
156	  flex: 1;
157	  width: 100%;
158	  max-width: 480px;
159	  margin: 0 auto;
160	  padding: 0 var(--spacing-page);
161	  padding-bottom: 100px;
162	}
163	@media (min-width: 768px) { .app-page-content { max-width: 720px; padding: 0 32px 48px; } }
164	@media (min-width: 1024px) { .app-page-content { max-width: 960px; } }
165	
166	/* ═══════════════════════════════════════════════════
167	   HEADER
168	   ═══════════════════════════════════════════════════ */
169	
170	.app-header {
171	  position: sticky;
172	  top: 0;
173	  z-index: 100;
174	  background: var(--color-surface);
175	  border-bottom: 1px solid var(--color-border);
176	  height: 56px;
177	  display: flex;
178	  align-items: center;
179	  padding: 0 var(--spacing-page);
180	}
181	
182	.app-header-inner {
183	  width: 100%;
184	  max-width: 480px;
185	  margin: 0 auto;
186	  display: flex;
187	  align-items: center;
188	  justify-content: space-between;
189	  gap: 12px;
190	}
191	@media (min-width: 768px) { .app-header-inner { max-width: 720px; } }
192	@media (min-width: 1024px) { .app-header-inner { max-width: 960px; } }
193	
194	.header-left { display: flex; align-items: center; gap: 8px; flex: 1; min-width: 0; }
195	.header-center { flex: 0 0 auto; text-align: center; }
196	.header-right { display: flex; align-items: center; gap: 8px; flex-shrink: 0; }
197	
198	.header-title {
199	  font-family: var(--font-heading);
200	  font-size: 1rem;
201	  font-weight: 700;
202	  color: var(--color-text);
203	  white-space: nowrap;
204	  overflow: hidden;
205	  text-overflow: ellipsis;
206	}
207	
208	.header-back-btn {
209	  width: 36px;
210	  height: 36px;
211	  display: flex;
212	  align-items: center;
213	  justify-content: center;
214	  border: none;
215	  background: var(--color-surface-alt);
216	  border-radius: var(--radius-sm);
217	  cursor: pointer;
218	  color: var(--color-text);
219	  transition: background 0.15s ease;
220	  flex-shrink: 0;
221	}
222	.header-back-btn:hover { background: var(--color-border); }
223	
224	.header-icon-btn {
225	  width: 36px;
226	  height: 36px;
227	  display: flex;
228	  align-items: center;
229	  justify-content: center;
230	  border: none;
231	  background: transparent;
232	  border-radius: var(--radius-sm);
233	  cursor: pointer;
234	  color: var(--color-text-secondary);
235	  transition: all 0.15s ease;
236	  position: relative;
237	  flex-shrink: 0;
238	}
239	.header-icon-btn:hover { background: var(--color-surface-alt); color: var(--color-text); }
240	
241	.header-badge {
242	  position: absolute;
243	  top: 2px;
244	  right: 2px;
245	  width: 16px;
246	  height: 16px;
247	  border-radius: 50%;
248	  background: var(--color-orange);
249	  color: #FFFFFF;
250	  font-size: 9px;
251	  font-weight: 700;
252	  display: flex;
253	  align-items: center;
254	  justify-content: center;
255	  border: 2px solid var(--color-surface);
256	}
257	
258	.brand-header {
259	  position: sticky;
260	  top: 0;
261	  z-index: 100;
262	  background: var(--color-surface);
263	  border-bottom: 1px solid var(--color-border);
264	  padding: 12px var(--spacing-page) 14px;
265	}
266	
267	.brand-header-inner { width: 100%; max-width: 480px; margin: 0 auto; }
268	
269	/* ═══════════════════════════════════════════════════
270	   BOTTOM TAB BAR
271	   ═══════════════════════════════════════════════════ */
272	
273	.tab-bar {
274	  position: fixed;
275	  bottom: 0;
276	  left: 0;
277	  right: 0;
278	  z-index: 100;
279	  background: var(--color-surface);
280	  border-top: 1px solid var(--color-border);
281	  padding: 6px 8px calc(6px + env(safe-area-inset-bottom, 0px));
282	}
283	
284	.tab-bar-inner {
285	  max-width: 480px;
286	  margin: 0 auto;
287	  display: flex;
288	  align-items: center;
289	  justify-content: space-around;
290	}
291	@media (min-width: 768px) { .tab-bar-inner { max-width: 720px; } }
292	
293	.tab-item {
294	  display: flex;
295	  flex-direction: column;
296	  align-items: center;
297	  gap: 3px;
298	  padding: 4px 12px;
299	  border-radius: var(--radius-sm);
300	  text-decoration: none;
301	  font-size: 10px;
302	  font-weight: 600;
303	  color: var(--color-text-muted);
304	  background: transparent;
305	  border: none;
306	  cursor: pointer;
307	  transition: color 0.15s ease;
308	  -webkit-tap-highlight-color: transparent;
309	  position: relative;
310	  font-family: var(--font-sans);
311	}
312	.tab-item.active { color: var(--color-orange); }
313	
314	.tab-item .tab-icon { width: 24px; height: 24px; display: flex; align-items: center; justify-content: center; }
315	
316	.tab-center-btn {
317	  width: 52px;
318	  height: 52px;
319	  border-radius: 50%;
320	  background: var(--color-orange);
321	  color: #FFFFFF;
322	  border: none;
323	  display: flex;
324	  align-items: center;
325	  justify-content: center;
326	  cursor: pointer;
327	  box-shadow: var(--shadow-orange);
328	  margin-top: -20px;
329	  transition: transform 0.15s ease, box-shadow 0.15s ease;
330	  -webkit-tap-highlight-color: transparent;
331	}
332	.tab-center-btn:hover { transform: scale(1.05); box-shadow: 0 6px 20px rgba(242,101,34,0.35); }
333	.tab-center-btn:active { transform: scale(0.95); }
334	
335	/* ═══════════════════════════════════════════════════
336	   CARDS
337	   ═══════════════════════════════════════════════════ */
338	
339	.card {
340	  background: var(--color-card);
341	  border-radius: var(--radius-lg);
342	  box-shadow: var(--shadow-card);
343	  transition: transform 0.2s ease, box-shadow 0.2s ease;
344	}
345	
346	.card-interactive, .card-hover { cursor: pointer; }
347	.card-interactive:hover, .card-hover:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
348	.card-interactive:active, .card-hover:active { transform: scale(0.98); }
349	
350	.card-padded { padding: 16px; }
351	.card-padded-sm { padding: 12px; }
352	.card-flat { background: var(--color-surface-alt); box-shadow: none; }
353	.card-orange { background: var(--color-orange-light); box-shadow: none; }
354	.card-orange-lt { background: var(--color-orange-light); }
355	.card-navy { background: var(--color-navy); color: #FFFFFF; box-shadow: none; }
356	.card-bordered { box-shadow: none; border: 1px solid var(--color-border); }
357	.card-sand { background: var(--sand); }
358	.card-blue-lt { background: var(--color-info-light); }
359	
360	/* ═══════════════════════════════════════════════════
361	   BUTTONS
362	   ═══════════════════════════════════════════════════ */
363	
364	.btn {
365	  display: inline-flex;
366	  align-items: center;
367	  justify-content: center;
368	  gap: 8px;
369	  padding: 12px 24px;
370	  border-radius: var(--radius-pill);
371	  font-size: 14px;
372	  font-weight: 600;
373	  font-family: var(--font-sans);
374	  border: none;
375	  cursor: pointer;
376	  line-height: 1.2;
377	  text-decoration: none;
378	  transition: all 0.18s ease;
379	  -webkit-tap-highlight-color: transparent;
380	  white-space: nowrap;
381	}
382	
383	.btn-primary { background: var(--color-orange); color: #FFFFFF; box-shadow: var(--shadow-orange); }
384	.btn-primary:hover { background: var(--color-orange-hover); }
385	.btn-primary:active { transform: scale(0.97); }
386	
387	.btn-secondary { background: var(--color-surface); color: var(--color-text); border: 1.5px solid var(--color-border); }
388	.btn-secondary:hover { background: var(--color-surface-alt); border-color: var(--color-border-hover); }
389	
390	.btn-ghost { background: transparent; color: var(--color-text-secondary); padding: 8px 16px; }
391	.btn-ghost:hover { background: var(--color-surface-alt); }
392	
393	.btn-navy { background: var(--color-navy); color: #FFFFFF; }
394	.btn-navy:hover { background: var(--color-navy-light); }
395	
396	.btn-sm { padding: 8px 16px; font-size: 12px; }
397	.btn-lg { padding: 16px 32px; font-size: 16px; }
398	.btn-full { width: 100%; }
399	.btn:disabled { opacity: 0.5; cursor: not-allowed; transform: none !important; }
400	
401	@keyframes btnSpin { to { transform: rotate(360deg); } }
402	
403	/* ═══════════════════════════════════════════════════
404	   BADGES
405	   ═══════════════════════════════════════════════════ */
406	
407	.badge { display: inline-flex; align-items: center; gap: 4px; padding: 3px 10px; border-radius: var(--radius-pill); font-size: 11px; font-weight: 700; letter-spacing: 0.01em; line-height: 1.3; }
408	.badge-orange { background: var(--color-orange-light); color: var(--color-orange); }
409	.badge-navy { background: var(--color-navy-subtle); color: var(--color-navy); }
410	.badge-success { background: var(--color-success-light); color: var(--color-success); }
411	.badge-error { background: var(--color-error-light); color: var(--color-error); }
412	.badge-warning { background: var(--color-warning-light); color: var(--color-warning); }
413	.badge-info { background: var(--color-info-light); color: var(--color-info); }
414	.badge-sm { padding: 2px 8px; font-size: 10px; }
415	
416	/* ═══════════════════════════════════════════════════
417	   FORMS & INPUTS
418	   ═══════════════════════════════════════════════════ */
419	
420	.input-field {
421	  width: 100%;
422	  height: 48px;
423	  padding: 0 16px;
424	  background: var(--color-surface);
425	  border: 1.5px solid var(--color-border);
426	  border-radius: var(--radius-md);
427	  font-size: 14px;
428	  font-family: var(--font-sans);
429	  color: var(--color-text);
430	  outline: none;
431	  transition: border-color 0.15s ease, box-shadow 0.15s ease;
432	}
433	.input-field:focus { border-color: var(--color-orange); box-shadow: 0 0 0 3px rgba(242,101,34,0.12); }
434	.input-field::placeholder { color: var(--color-text-muted); }
435	
436	.input-label { display: block; font-size: 13px; font-weight: 600; color: var(--color-text); margin-bottom: 6px; }
437	.input-helper { font-size: 12px; color: var(--color-text-tertiary); margin-top: 4px; }
438	.input-error { font-size: 12px; color: var(--color-error); margin-top: 4px; }
439	
440	/* ═══════════════════════════════════════════════════
441	   SEARCH BAR
442	   ═══════════════════════════════════════════════════ */
443	
444	.search-bar { position: relative; width: 100%; }
445	.search-bar input {
446	  width: 100%;
447	  height: 48px;
448	  padding: 0 16px 0 44px;
449	  background: var(--color-surface-alt);
450	  border: 1.5px solid var(--color-border);
451	  border-radius: var(--radius-pill);
452	  font-size: 14px;
453	  font-family: var(--font-sans);
454	  color: var(--color-text);
455	  outline: none;
456	  transition: border-color 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
457	}
458	.search-bar input:focus { border-color: var(--color-orange); box-shadow: 0 0 0 3px rgba(242,101,34,0.12); background: var(--color-surface); }
459	.search-bar input::placeholder { color: var(--color-text-muted); }
460	
461	/* ═══════════════════════════════════════════════════
462	   MODAL / BOTTOM SHEET
463	   ═══════════════════════════════════════════════════ */
464	
465	.modal-backdrop { position: fixed; inset: 0; background: rgba(0,0,0,0.5); z-index: 200; display: flex; align-items: flex-end; justify-content: center; padding: 0; }
466	@media (min-width: 768px) { .modal-backdrop { align-items: center; padding: 24px; } }
467	
468	.modal-content { background: var(--color-surface); border-radius: var(--radius-2xl) var(--radius-2xl) 0 0; width: 100%; max-width: 480px; max-height: 90vh; overflow-y: auto; padding: 20px; }
469	@media (min-width: 768px) { .modal-content { border-radius: var(--radius-2xl); max-height: 80vh; } }
470	
471	.modal-handle { width: 36px; height: 4px; border-radius: 2px; background: var(--color-border-hover); margin: 0 auto 16px; }
472	@media (min-width: 768px) { .modal-handle { display: none; } }
473	
474	/* ═══════════════════════════════════════════════════
475	   TOAST / SNACKBAR
476	   ═══════════════════════════════════════════════════ */
477	
478	.toast-container { position: fixed; top: 16px; left: 50%; transform: translateX(-50%); z-index: 300; display: flex; flex-direction: column; gap: 8px; pointer-events: none; width: calc(100% - 32px); max-width: 400px; }
479	.toast { background: var(--color-navy); color: #FFFFFF; padding: 12px 16px; border-radius: var(--radius-md); font-size: 13px; font-weight: 600; display: flex; align-items: center; gap: 10px; box-shadow: var(--shadow-lg); pointer-events: auto; animation: toastIn 0.3s ease-out; }
480	.toast-success { background: var(--color-success); }
481	.toast-error { background: var(--color-error); }
482	.toast-warning { background: var(--color-warning); }
483	
484	@keyframes toastIn { from { opacity: 0; transform: translateY(-12px); } to { opacity: 1; transform: translateY(0); } }
485	
486	/* ═══════════════════════════════════════════════════
487	   PROGRESS
488	   ═══════════════════════════════════════════════════ */
489	
490	.progress-track { width: 100%; height: 6px; background: var(--color-border); border-radius: var(--radius-pill); overflow: hidden; }
491	.progress-fill { height: 100%; border-radius: var(--radius-pill); background: var(--color-orange); transition: width 0.5s cubic-bezier(0.4,0,0.2,1); }
492	
493	/* ═══════════════════════════════════════════════════
494	   SECTIONS & EMPTY STATE
495	   ═══════════════════════════════════════════════════ */
496	
497	.section-title { font-family: var(--font-heading); font-size: 1.05rem; font-weight: 700; color: var(--color-text); }
498	
499	.empty-state { display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 48px 24px; text-align: center; }
500	.empty-state-icon { width: 72px; height: 72px; border-radius: 50%; background: var(--color-surface-alt); display: flex; align-items: center; justify-content: center; margin-bottom: 16px; color: var(--color-text-muted); }
501	.empty-state-title { font-family: var(--font-heading); font-size: 1.1rem; font-weight: 700; color: var(--color-text); margin-bottom: 6px; }
502	.empty-state-desc { font-size: 14px; color: var(--color-text-tertiary); max-width: 280px; line-height: 1.5; margin-bottom: 20px; }
503	
504	/* ═══════════════════════════════════════════════════
505	   PAGE HEADER
506	   ═══════════════════════════════════════════════════ */
507	
